import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

function hexToRgb(value) {
  const hex = String(value || '').replace('#', '');
  const normalized = hex.length === 3
    ? hex.split('').map((part) => part + part).join('')
    : hex.padEnd(6, '0').slice(0, 6);

  return [
    parseInt(normalized.slice(0, 2), 16) / 255,
    parseInt(normalized.slice(2, 4), 16) / 255,
    parseInt(normalized.slice(4, 6), 16) / 255,
  ];
}

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const root = new Group();
  const ownedGeometries = [];
  const ownedMaterials = [];
  const ownedTextures = [];
  const timelines = [];
  let disposed = false;

  const visualSpec = config.intent?.visualSpec ?? {};
  const colors = visualSpec.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const surfaceRgb = hexToRgb(colors.surface);
  const inkRgb = hexToRgb(colors.ink);

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMaterial = new MeshBasicNodeMaterial({
    toneMapped: false,
  });

  const backdropGradient = smoothstep(0.0, 1.0, uv().y);
  backdropMaterial.colorNode = mix(
    vec3(surfaceRgb[0], surfaceRgb[1], surfaceRgb[2]),
    vec3(inkRgb[0], inkRgb[1], inkRgb[2]),
    backdropGradient,
  );

  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.set(0, -0.15, -2.5);
  root.add(backdrop);
  ownedGeometries.push(backdropGeometry);
  ownedMaterials.push(backdropMaterial);

  const panelGeometry = new PlaneGeometry(5.8, 1.35);
  const panelMaterial = new MeshBasicNodeMaterial({
    color: colors.surface,
    transparent: true,
    opacity: 0.94,
  });
  const panel = new Mesh(panelGeometry, panelMaterial);
  panel.position.set(0, 0.15, -1.55);
  root.add(panel);
  ownedGeometries.push(panelGeometry);
  ownedMaterials.push(panelMaterial);

  const imageUrl = config.imageUrl ?? visualSpec.imageUrl;
  if (imageUrl) {
    const imageGeometry = new PlaneGeometry(2.55, 1.35);
    const imageMaterial = new MeshBasicNodeMaterial({
      color: colors.paper,
      transparent: true,
      opacity: 0.18,
      toneMapped: false,
    });
    const imagePlane = new Mesh(imageGeometry, imageMaterial);
    imagePlane.position.set(1.62, -0.72, -0.7);
    root.add(imagePlane);
    ownedGeometries.push(imageGeometry);
    ownedMaterials.push(imageMaterial);

    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      if (disposed) {
        texture.dispose?.();
        return;
      }

      ownedTextures.push(texture);
      imageMaterial.map = texture;
      imageMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  const accentGeometry = new PlaneGeometry(1.15, 0.035);
  const accentMaterial = new MeshBasicNodeMaterial({
    color: colors.accent,
    toneMapped: false,
  });
  const accent = new Mesh(accentGeometry, accentMaterial);
  accent.position.set(-2.15, 0.92, 0.15);
  root.add(accent);
  ownedGeometries.push(accentGeometry);
  ownedMaterials.push(accentMaterial);

  const items = config.textContent ?? visualSpec.textContent ?? [];
  for (const item of items) {
    if (!item || typeof item.text !== 'string') continue;

    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 42,
      color: colors.paper,
      align: 'center',
      maxWidthPx: 880,
      letterSpacingPx: item.typography?.letterSpacingPx ?? 0,
    });

    textObject.position.set(0, 0.2, 0.25);
    root.add(textObject);
  }

  root.userData.handlers = {};

  root.scale.set(0.985, 0.985, 0.985);
  const entrance = gsap.timeline({
    defaults: {
      ease: 'power3.out',
    },
  });

  entrance.to(root.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.7,
  });

  timelines.push(entrance);

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline.kill();
    }

    for (const texture of ownedTextures) {
      texture.dispose?.();
    }

    for (const material of ownedMaterials) {
      material.dispose?.();
    }

    for (const geometry of ownedGeometries) {
      geometry.dispose?.();
    }

    root.clear();
  };

  return root;
}
